// PlacementSphere — ghoomta hua Earth logo (canvas, no library)
// Real continent texture + lighting + clouds + atmosphere glow, aur "PLACEMENT SPHERE" ring jo globe ke peeche jaake chhup jata hai.
(function () {
  'use strict';
  var TEX_SRC = 'data:image/jpeg;base64,';
  // Do lines: PLACEMENT (upar) + SPHERE (neeche), dono ek saath globe ke around ghoomte hain, letters seedhe rehte hain
  var LINES = [{ t: 'PLACEMENT', y: 0.27 }, { t: 'SPHERE', y: -0.27 }], STEP = 15 * Math.PI / 180;
  var PITCH = 16 * Math.PI / 180, ROLL = -9 * Math.PI / 180;           // globe ka jhukaav (north pole thoda front mein)
  var EARTH_SPIN = 2 * Math.PI / 28, CYCLE = 9, HOLD = 0.72, SWAY = 0.17;   // 9s ka cycle: ~6.5s text aage seedha (halka sa sway), phir ek tez chakkar globe ke peeche se      // seconds per rotation
  var reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;

  // ── CSS ──
  var st = document.createElement('style');
  st.textContent = '.ps-globe{--s:46px;display:inline-block;position:relative;flex:0 0 auto;vertical-align:middle;width:calc(var(--s)*1.34);height:calc(var(--s)*1.34);margin:calc(var(--s)*-.17) calc(var(--s)*-.07)}' +
    '.ps-globe canvas{display:block;width:100%;height:100%}@media (max-width:600px){.ps-globe{--s:38px}}';
  document.head.appendChild(st);

  var cP = Math.cos(PITCH), sP = Math.sin(PITCH), cR = Math.cos(ROLL), sR = Math.sin(ROLL);
  var LIGHT = (function () { var l = [-0.55, 0.5, 0.68], m = Math.hypot(l[0], l[1], l[2]); return [l[0] / m, l[1] / m, l[2] / m]; })();
  var HALF = (function () { var h = [LIGHT[0], LIGHT[1], LIGHT[2] + 1], m = Math.hypot(h[0], h[1], h[2]); return [h[0] / m, h[1] / m, h[2] / m]; })();

  // ── shared texture + cloud layer ──
  var texPix = null, TW = 0, TH = 0, texCache = {}, clouds = null, ready = false, waiters = [];
  function makeClouds() {
    var W = 256, H = 128, out = new Float32Array(W * H), amp = 1, tot = 0, seed = 11;
    function rnd() { seed = (seed * 16807) % 2147483647; return seed / 2147483647; }
    for (var o = 0; o < 5; o++) {
      var gw = 4 << o, gh = 2 << o, g = new Float32Array(gw * (gh + 1));
      for (var i = 0; i < g.length; i++) g[i] = rnd();
      for (var y = 0; y < H; y++) for (var x = 0; x < W; x++) {
        var fx = x / W * gw, fy = y / H * gh, x0 = Math.floor(fx), y0 = Math.floor(fy), tx = fx - x0, ty = fy - y0;
        tx = tx * tx * (3 - 2 * tx); ty = ty * ty * (3 - 2 * ty);
        var a = g[y0 * gw + x0 % gw], b = g[y0 * gw + (x0 + 1) % gw], c = g[(y0 + 1) * gw + x0 % gw], d = g[(y0 + 1) * gw + (x0 + 1) % gw];
        out[y * W + x] += amp * ((a + (b - a) * tx) * (1 - ty) + (c + (d - c) * tx) * ty);
      }
      tot += amp; amp *= 0.55;
    }
    for (var k = 0; k < out.length; k++) out[k] /= tot;
    return { w: W, h: H, d: out };
  }
  function texFor(width) {
    width = Math.max(256, Math.min(1024, width));
    if (texCache[width]) return texCache[width];
    var c = document.createElement('canvas'); c.width = width; c.height = width / 2;
    var x = c.getContext('2d'); x.imageSmoothingEnabled = true; x.imageSmoothingQuality = 'high';
    x.drawImage(texImg, 0, 0, c.width, c.height);
    return (texCache[width] = { w: c.width, h: c.height, d: x.getImageData(0, 0, c.width, c.height).data });
  }
  var texImg = new Image();
  texImg.onload = function () { clouds = makeClouds(); ready = true; waiters.forEach(function (f) { f(); }); waiters = []; };
  texImg.src = TEX_SRC;

  var smooth = function (a, b, x) { var t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); };

  // ── one globe ──
  function Globe(box) {
    var self = this, css = box.getBoundingClientRect().width || 54, dpr = Math.min(window.devicePixelRatio || 1, 3);
    var N = Math.round(css * dpr), cv = document.createElement('canvas');
    cv.width = cv.height = N; box.innerHTML = ''; box.appendChild(cv);
    var ctx = cv.getContext('2d'), cx = N / 2, cy = N / 2, R = N / 2 / 1.34, Rr = R * 1.14;
    var tex = texFor(Math.round(R * 2 * 3.3));
    var off = document.createElement('canvas'); off.width = off.height = N;
    var octx = off.getContext('2d'), img = octx.createImageData(N, N), buf = img.data;

    // static per-pixel data
    var px = [], base = [], rowV = [], shade = [], rim = [], spec = [], cov = [];
    for (var y = 0; y < N; y++) for (var x = 0; x < N; x++) {
      var dx = x + .5 - cx, dy = y + .5 - cy, dist = Math.sqrt(dx * dx + dy * dy);
      if (dist > R + 1) continue;
      var nx = dx / R, ny = -dy / R, nz2 = 1 - nx * nx - ny * ny, nz = nz2 > 0 ? Math.sqrt(nz2) : 0;
      if (nz2 <= 0) { var m = Math.hypot(nx, ny); nx /= m; ny /= m; nz = 0; }
      var y1 = ny * cP + nz * sP, z1 = -ny * sP + nz * cP;                // pitch
      var x2 = nx * cR - y1 * sR, y2 = nx * sR + y1 * cR;                 // roll
      var lat = Math.asin(Math.max(-1, Math.min(1, y2)));
      var lam = nx * LIGHT[0] + ny * LIGHT[1] + nz * LIGHT[2];
      var nh = Math.max(0, nx * HALF[0] + ny * HALF[1] + nz * HALF[2]);
      px.push(y * N + x); base.push(Math.atan2(x2, z1)); rowV.push((0.5 - lat / Math.PI) * (tex.h - 1));
      shade.push(0.2 + 0.95 * Math.pow(Math.max(0, lam), 0.8)); rim.push(Math.pow(1 - nz, 2.6)); spec.push(Math.pow(nh, 70));
      cov.push(Math.max(0, Math.min(1, R - dist + 0.5)));
    }
    var n = px.length, TW_ = tex.w, TD = tex.d;

    function drawEarth(rot) {
      var cl = clouds, cu = rot * 1.07;
      for (var i = 0; i < n; i++) {
        var u = (((base[i] - rot) / (2 * Math.PI) + 0.5) % 1 + 1) % 1 * TW_, v = rowV[i];
        var x0 = u | 0, y0 = v | 0, fx = u - x0, fy = v - y0, x1 = (x0 + 1) % TW_, y1 = Math.min(tex.h - 1, y0 + 1);
        var a = (y0 * TW_ + x0) * 4, b = (y0 * TW_ + x1) * 4, c = (y1 * TW_ + x0) * 4, d = (y1 * TW_ + x1) * 4;
        var r = (TD[a] * (1 - fx) + TD[b] * fx) * (1 - fy) + (TD[c] * (1 - fx) + TD[d] * fx) * fy;
        var g = (TD[a + 1] * (1 - fx) + TD[b + 1] * fx) * (1 - fy) + (TD[c + 1] * (1 - fx) + TD[d + 1] * fx) * fy;
        var bl = (TD[a + 2] * (1 - fx) + TD[b + 2] * fx) * (1 - fy) + (TD[c + 2] * (1 - fx) + TD[d + 2] * fx) * fy;
        var ocean = bl > r * 1.4 && bl > g * 1.08;
        // clouds
        var cuu = ((((base[i] - cu) / (2 * Math.PI) + 0.5) % 1 + 1) % 1) * cl.w, cvv = (rowV[i] / (tex.h - 1)) * (cl.h - 1);
        var cd = cl.d[(cvv | 0) * cl.w + (cuu | 0)];
        var ca = smooth(0.52, 0.7, cd) * 0.78;
        var s = shade[i];
        r = r * s; g = g * s; bl = bl * s;
        if (ocean) { var sp = spec[i] * 0.7 * (1 - ca); r += 255 * sp; g += 255 * sp; bl += 255 * sp; }
        r = r * (1 - ca) + 245 * s * ca; g = g * (1 - ca) + 247 * s * ca; bl = bl * (1 - ca) + 252 * s * ca;
        var rm = rim[i] * (0.35 + 0.65 * Math.min(1, s));                  // atmosphere rim
        r += 70 * rm; g += 150 * rm; bl += 255 * rm;
        var o = px[i] * 4;
        buf[o] = r > 255 ? 255 : r; buf[o + 1] = g > 255 ? 255 : g; buf[o + 2] = bl > 255 ? 255 : bl; buf[o + 3] = cov[i] * 255;
      }
      octx.putImageData(img, 0, 0);
    }

    // band ka 3D point -> screen (gy = height on the globe, theta = angle around it)
    function ringPt(theta, gy) {
      var gx = Math.sin(theta) * Rr, gz = Math.cos(theta) * Rr; gy = gy * R;
      var xp = gx * cR + gy * sR, yp = -gx * sR + gy * cR;               // un-roll
      var vy = yp * cP - gz * sP, vz = yp * sP + gz * cP;                // un-pitch
      return { x: cx + xp, y: cy - vy, z: vz, vx: xp, vy: vy };
    }
    function ringPhase(t) {
      var u = (t % CYCLE) / CYCLE;
      if (u < HOLD) return -SWAY + 2 * SWAY * (u / HOLD);                   // aage rukta hua, halka sa left->right
      var k = (u - HOLD) / (1 - HOLD), e = k < .5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2;   // ease in-out
      return SWAY + (2 * Math.PI - 2 * SWAY) * e;                           // poora chakkar, peeche se hoke wapas
    }
    function ring(t, front) {
      var fs = R * 0.42, phase = ringPhase(t);
      ctx.font = '800 ' + fs + 'px "DM Sans", Arial, sans-serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.lineJoin = 'round';
      LINES.forEach(function (ln) {
        var n_ = ln.t.length;
        for (var i = 0; i < n_; i++) {
          var th = phase + (i - (n_ - 1) / 2) * STEP, p = ringPt(th, ln.y), isFront = p.z >= 0;
          if (isFront !== front) continue;
          if (!front && p.vx * p.vx + p.vy * p.vy < R * R) continue;      // globe ke peeche -> chhupa hua
          var q = ringPt(th + 0.04, ln.y), q0 = ringPt(th - 0.04, ln.y);
          var ang = Math.atan2(q.y - q0.y, q.x - q0.x) * 0.55;            // thoda sa curve follow, letters tedhe nahi
          if (ang > 1.2 || ang < -1.2) ang = 0;
          var face = Math.max(0, p.z / Rr), sx = 0.5 + 0.5 * face;        // kinare pe letters patle (wrap effect)
          var alpha = front ? Math.min(1, 0.3 + face * 1.5) : 0.4;
          ctx.save(); ctx.translate(p.x, p.y); ctx.rotate(ang); ctx.scale(sx, 1); ctx.globalAlpha = alpha;
          ctx.lineWidth = fs * 0.22; ctx.strokeStyle = 'rgba(5,8,40,.92)'; ctx.strokeText(ln.t[i], 0, 0);
          ctx.fillStyle = '#fff'; ctx.fillText(ln.t[i], 0, 0); ctx.restore();
        }
      });
    }

    this.render = function (t) {
      drawEarth(1.9 - t * EARTH_SPIN);
      ctx.clearRect(0, 0, N, N);
      ring(t, false);
      var gl = ctx.createRadialGradient(cx, cy, R * 0.96, cx, cy, R * 1.2);
      gl.addColorStop(0, 'rgba(90,160,255,.55)'); gl.addColorStop(0.4, 'rgba(70,130,255,.16)'); gl.addColorStop(1, 'rgba(70,130,255,0)');
      ctx.fillStyle = gl; ctx.beginPath(); ctx.arc(cx, cy, R * 1.2, 0, 7); ctx.fill();
      ctx.drawImage(off, 0, 0);
      ring(t, true);
    };
    this.visible = true;
    if ('IntersectionObserver' in window) new IntersectionObserver(function (e) { self.visible = e[0].isIntersecting; }).observe(box);
  }

  var globes = [], t0 = performance.now(), running = false;
  function frame(now) {
    if (document.hidden) { running = false; return; }
    var t = (now - t0) / 1000;
    for (var i = 0; i < globes.length; i++) if (globes[i].visible) globes[i].render(t);
    requestAnimationFrame(frame);
  }
  function start() {
    document.querySelectorAll('.ps-globe').forEach(function (b) { globes.push(new Globe(b)); });
    if (reduce) globes.forEach(function (g) { g.render(0); });
    else { running = true; requestAnimationFrame(frame); }
  }
  document.addEventListener('visibilitychange', function () { if (!document.hidden && !running && !reduce && globes.length) { running = true; requestAnimationFrame(frame); } });
  function init() { if (ready) start(); else waiters.push(start); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();
